const toId = (value) => {
  if (!value) return '';
  if (typeof value === 'string') return value;
  if (value.$oid) return value.$oid;
  if (typeof value.toHexString === 'function') return value.toHexString();
  if (typeof value.toString === 'function') {
    const s = value.toString();
    return s !== '[object Object]' ? s : '';
  }
  return String(value);
};

const pickText = (value, lang) => {
  if (!value) return '';
  if (typeof value === 'string') return value;
  if (typeof value === 'object') {
    if (lang && typeof value[lang] === 'string') return value[lang];
    for (const v of Object.values(value)) {
      if (typeof v === 'string' && v.trim()) return v;
    }
  }
  return '';
};

let docs = input;
if (typeof docs === 'string') {
  try {
    docs = JSON.parse(docs);
  } catch {
    docs = [];
  }
}
if (!Array.isArray(docs)) docs = [];

const artifacts = [];

for (const doc of docs) {
  if (!doc || typeof doc !== 'object') continue;

  const documentId = toId(doc._id);
  const courseId = toId(doc.courseId);
  const subItemId = toId(doc.subItemId);
  const tableOfContentId = toId(doc.tableOfContentId);

  const courseLang = String(doc.course?.courseLanguage || 'de');
  const courseTitle = pickText(doc.course?.title, courseLang);
  const tableOfContentTitle = pickText(doc.tableOfContent?.title, courseLang);
  const subTableOfContentTitle = pickText(doc.subTableOfContent?.title, courseLang);

  const section = Array.isArray(doc.sections) && doc.sections.length ? doc.sections[0] : null;
  const blocks = Array.isArray(section?.blocks) ? section.blocks : [];

  const vocabularies = [];
  const grammars = [];

  for (const block of blocks) {
    if (!block || typeof block !== 'object') continue;
    const tool = String(block.tool || '');
    const lang = String(block.language || courseLang || 'de');
    const content = block.content && typeof block.content === 'object' ? block.content : {};

    if (tool === 'vocabulary') {
      const items = Array.isArray(content.items)
        ? content.items.map((item) => ({
            text: item?.text || '',
            wordId: toId(item?.wordId),
          }))
        : [];
      vocabularies.push({
        blockId: block.blockId || '',
        language: lang,
        title: pickText(content.title, lang),
        items,
      });
    }

    if (tool === 'grammar') {
      const examples = Array.isArray(content.examples) ? content.examples : [];
      grammars.push({
        blockId: block.blockId || '',
        language: lang,
        title: pickText(content.title, lang),
        example: typeof examples[0] === 'string' ? examples[0] : pickText(examples[0], lang),
      });
    }
  }

  if (!vocabularies.length && !grammars.length) continue;

  const metadata = {
    documentId,
    courseId,
    subItemId,
    tableOfContentId,
    courseTitle,
    tableOfContentTitle,
    subTableOfContentTitle,
  };

  const titleParts = [tableOfContentTitle, subTableOfContentTitle].filter(Boolean);
  const title = titleParts.length ? titleParts.join(' — ') : documentId;

  const tags = [courseId, subItemId, tableOfContentId, documentId].filter(Boolean).join(',');

  artifacts.push({
    logicalId: documentId,
    title,
    metadata,
    tags,
    content: {
      documentId,
      courseId,
      subItemId,
      tableOfContentId,
      courseTitle,
      tableOfContentTitle,
      subTableOfContentTitle,
      vocabularies,
      grammars,
    },
  });
}

return {
  artifacts,
  count: artifacts.length,
};
